-- Read-only and secret-free. Save the result as a private operator artifact.
with retired(signature) as(values('public.configure_byus_queue_maintenance(text,text)'),('public.configure_byus_worker_invocation(text,text,text)'),('public.get_infrastructure_health()')),
objects as(select signature,to_regprocedure(signature) oid from retired),
bucket_rows as(select id,jsonb_build_object('id',id,'name',name,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types) value from storage.buckets),
object_rows as(select id,jsonb_build_object('id',id,'bucket_id',bucket_id,'name',name,'metadata',metadata,'user_metadata',to_jsonb(s)->'user_metadata') value from storage.objects s)
select jsonb_build_object(
 'format',1,'version',current_setting('server_version_num'),'database',current_database(),
 'storageColumns',(select jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'type',data_type,'udtSchema',udt_schema,'udtName',udt_name,'nullable',is_nullable,'defaultHash',md5(column_default)) order by table_name,ordinal_position) from information_schema.columns where table_schema='storage' and table_name in('buckets','objects')),
 'storageRelations',(select jsonb_agg(jsonb_build_object('table',c.relname,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'rls',c.relrowsecurity,'constraints',(select jsonb_agg(jsonb_build_object('name',conname,'definition',pg_get_constraintdef(oid)) order by conname) from pg_constraint where conrelid=c.oid),'triggers',(select jsonb_agg(jsonb_build_object('name',tgname,'enabled',tgenabled,'definitionHash',md5(pg_get_triggerdef(oid))) order by tgname) from pg_trigger where tgrelid=c.oid and not tgisinternal)) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='storage' and c.relname in('buckets','objects')),
 'storageProjection',jsonb_build_object(
  'buckets',(select jsonb_build_object('rows',count(*)::text,'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(value order by id collate "C"),'[]')::text,'UTF8')),'hex')) from bucket_rows),
  'objects',(select jsonb_build_object('rows',count(*)::text,'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(value order by id::text collate "C"),'[]')::text,'UTF8')),'hex')) from object_rows)),
 'retirement',(select jsonb_agg(jsonb_build_object('signature',o.signature,'exists',o.oid is not null,'definitionHash',case when o.oid is not null then md5(pg_get_functiondef(o.oid)) end,'incomingCatalogDependencies',(select coalesce(jsonb_agg(jsonb_build_object('class',d.classid::regclass::text,'object',pg_describe_object(d.classid,d.objid,d.objsubid),'type',d.deptype)),'[]') from pg_depend d where d.refclassid='pg_proc'::regclass and d.refobjid=o.oid),'incomingCronJobs',(select coalesce(jsonb_agg(jsonb_build_object('name',jobname,'schedule',schedule,'active',active)),'[]') from cron.job where command ~ ('\m'||split_part(split_part(o.signature,'.',2),'(',1)||'\s*\(')),'incomingRoutineReferences',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid))),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.oid<>o.oid and p.prosrc ~ ('\m'||split_part(split_part(o.signature,'.',2),'(',1)||'\s*\('))) order by signature) from objects o),
 'providerRoutines',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'securityDefiner',p.prosecdef,'settingsHash',md5(p.proconfig::text),'definitionHash',md5(pg_get_functiondef(p.oid))) order by p.proname,pg_get_function_identity_arguments(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind in('f','p') and p.prosrc ~* '\m(auth|storage|cron|net|vault)\s*\.')
);
